from collections import Counter, deque
src='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            while q:
                y,x = q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells) >= 6:
                ys = [y for y,x in cells]; xs = [x for y,x in cells]
                objects.append((color,min(ys),max(ys),min(xs),max(xs)))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for color,r0,r1,c0,c1 in objects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
    return out
'''
